CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS warehouses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),code VARCHAR(30) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,address TEXT,phone VARCHAR(50),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),warehouse_id UUID REFERENCES warehouses(id) ON DELETE SET NULL,name VARCHAR(120) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'storekeeper',active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS categories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name VARCHAR(120) UNIQUE NOT NULL,description TEXT);
CREATE TABLE IF NOT EXISTS brands (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name VARCHAR(120) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS suppliers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name VARCHAR(180) NOT NULL,contact_person VARCHAR(120),phone VARCHAR(50),email VARCHAR(180),address TEXT,tax_number VARCHAR(80),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),category_id UUID REFERENCES categories(id) ON DELETE SET NULL,brand_id UUID REFERENCES brands(id) ON DELETE SET NULL,default_supplier_id UUID REFERENCES suppliers(id) ON DELETE SET NULL,name VARCHAR(180) NOT NULL,sku VARCHAR(80) UNIQUE NOT NULL,barcode VARCHAR(120) UNIQUE,description TEXT,unit VARCHAR(30) NOT NULL DEFAULT 'item',cost_price NUMERIC(14,2) NOT NULL DEFAULT 0,selling_price NUMERIC(14,2) NOT NULL DEFAULT 0,reorder_level NUMERIC(14,2) NOT NULL DEFAULT 5,track_batch BOOLEAN NOT NULL DEFAULT FALSE,track_expiry BOOLEAN NOT NULL DEFAULT FALSE,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS inventory (warehouse_id UUID NOT NULL REFERENCES warehouses(id) ON DELETE CASCADE,product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,quantity NUMERIC(14,2) NOT NULL DEFAULT 0,reserved_quantity NUMERIC(14,2) NOT NULL DEFAULT 0,PRIMARY KEY (warehouse_id,product_id));
CREATE TABLE IF NOT EXISTS inventory_batches (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),warehouse_id UUID NOT NULL REFERENCES warehouses(id) ON DELETE CASCADE,product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,batch_number VARCHAR(100),expiry_date DATE,quantity NUMERIC(14,2) NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS purchase_orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),po_number VARCHAR(50) UNIQUE NOT NULL,warehouse_id UUID NOT NULL REFERENCES warehouses(id),supplier_id UUID NOT NULL REFERENCES suppliers(id),created_by UUID NOT NULL REFERENCES users(id),status VARCHAR(30) NOT NULL DEFAULT 'draft',expected_date DATE,subtotal NUMERIC(14,2) NOT NULL DEFAULT 0,tax NUMERIC(14,2) NOT NULL DEFAULT 0,total NUMERIC(14,2) NOT NULL DEFAULT 0,notes TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS purchase_order_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),purchase_order_id UUID NOT NULL REFERENCES purchase_orders(id) ON DELETE CASCADE,product_id UUID NOT NULL REFERENCES products(id),quantity NUMERIC(14,2) NOT NULL,unit_cost NUMERIC(14,2) NOT NULL,received_quantity NUMERIC(14,2) NOT NULL DEFAULT 0,line_total NUMERIC(14,2) NOT NULL);
CREATE TABLE IF NOT EXISTS stock_transfers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),transfer_number VARCHAR(50) UNIQUE NOT NULL,from_warehouse_id UUID NOT NULL REFERENCES warehouses(id),to_warehouse_id UUID NOT NULL REFERENCES warehouses(id),created_by UUID NOT NULL REFERENCES users(id),status VARCHAR(30) NOT NULL DEFAULT 'draft',notes TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS stock_transfer_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),transfer_id UUID NOT NULL REFERENCES stock_transfers(id) ON DELETE CASCADE,product_id UUID NOT NULL REFERENCES products(id),quantity NUMERIC(14,2) NOT NULL);
CREATE TABLE IF NOT EXISTS stock_movements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),warehouse_id UUID NOT NULL REFERENCES warehouses(id),product_id UUID NOT NULL REFERENCES products(id),movement_type VARCHAR(40) NOT NULL,quantity NUMERIC(14,2) NOT NULL,balance_after NUMERIC(14,2),reference_type VARCHAR(40),reference_id UUID,note TEXT,created_by UUID REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),warehouse_id UUID REFERENCES warehouses(id),user_id UUID REFERENCES users(id),action VARCHAR(80) NOT NULL,entity_type VARCHAR(80),entity_id UUID,method VARCHAR(10),path TEXT,ip_address VARCHAR(80),before_data JSONB,after_data JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
INSERT INTO warehouses(code,name,address,phone) VALUES ('WH-COL','Colombo Central Warehouse','Colombo, Sri Lanka','0112000001'),('WH-GAM','Gampaha Warehouse','Gampaha, Sri Lanka','0332000002') ON CONFLICT(code) DO NOTHING;
