INSERT INTO inventory(warehouse_id,product_id,quantity) SELECT w.id,p.id,CASE WHEN w.code='WH-COL' THEN 50 ELSE 25 END FROM warehouses w CROSS JOIN products p ON CONFLICT(warehouse_id,product_id) DO NOTHING;
